import { forwardRef } from 'react'

import { Polymorphic } from '../../../utils/PolymorphicUtils'
import { ResumeData } from '../resume-page'

export type IntroductionImageProps = Pick<ResumeData, 'introduction'>

export const IntroductionImage = forwardRef(function IntroductionImage(
  { as: Component = 'img', introduction, ...props },
  ref,
) {
  return (
    <Component
      alt={introduction.name}
      className="h-36 w-36 rounded-3xl border border-ink-200/70 object-cover shadow-sm md:h-40 md:w-40 print:border-none print:shadow-none"
      src={introduction.imageSrc}
      {...props}
      ref={ref}
    />
  )
}) as Polymorphic<'img', IntroductionImageProps>
