import { forwardRef } from 'react'
import { useTranslation } from 'react-i18next'

import { Polymorphic } from '../../../utils/PolymorphicUtils'
import { Section } from '../../shared/section/section'
import { Stack } from '../../shared/stack/Stack'
import { ProjectData } from '../resume-page'
import { ProjectHistoryEntry } from './project-history-entry'

export type ProjectHistoryProps = {
  projects: ProjectData[]
}

export const ProjectHistory = forwardRef(function ProjectHistory(
  { projects, ...props },
  ref,
) {
  const { t } = useTranslation()

  return (
    <Section headline={t('resume.projects.headline')} {...props} ref={ref}>
      <Stack
        direction="column"
        gap={8 * 4}
        className="border-l border-ink-200 dark:border-ink-400"
      >
        {projects.map((p) => (
          <ProjectHistoryEntry key={p.title} {...p} />
        ))}
      </Stack>
    </Section>
  )
}) as Polymorphic<'div', ProjectHistoryProps>
