import { Mail, Phone } from 'lucide-react'
import { forwardRef } from 'react'

import { Polymorphic } from '../../../utils/PolymorphicUtils'
import { Link } from '../../shared/link/link'
import { Stack } from '../../shared/stack/Stack'
import { ResumeData } from '../resume-page'

export type IntroductionContentContactsProps = Pick<ResumeData, 'contacts'>

export const IntroductionContentContacts = forwardRef(
  function IntroductionContentContacts({ contacts, ...props }, ref) {
    return (
      <Stack
        direction={{ sm: 'column', md: 'row' }}
        align="center"
        gap={4 * 4}
        {...props}
        ref={ref}
      >
        <Link
          href={`tel:${contacts.phone}`}
          emphasis="default"
          iconStart={<Phone className="h-4 w-4 text-ink-700" />}
        >
          {contacts.phone}
        </Link>
        <Link
          href={`mailto:${contacts.email}`}
          emphasis="default"
          iconStart={<Mail className="h-4 w-4 text-ink-700" />}
        >
          {contacts.email}
        </Link>
      </Stack>
    )
  },
) as Polymorphic<'div', IntroductionContentContactsProps>
