import { forwardRef } from 'react'

import { Polymorphic } from '../../../utils/PolymorphicUtils'
import { Stack } from '../../shared/stack/Stack'
import { ResumeData } from '../resume-page'
import { IntroductionContentContacts } from './introduction-content-contacts'
import { IntroductionContentDetails } from './introduction-content-details'

export type IntroductionContentProps = Pick<
  ResumeData,
  'introduction' | 'contacts'
>

export const IntroductionContent = forwardRef(function IntroductionContent(
  { introduction, contacts, ...props },
  ref,
) {
  return (
    <Stack
      direction="column"
      align={{ sm: 'center', md: 'start' }}
      gap={{ sm: 6 * 8, md: 4 * 8 }}
      {...props}
      ref={ref}
    >
      <IntroductionContentDetails introduction={introduction} />
      <IntroductionContentContacts contacts={contacts} />
    </Stack>
  )
}) as Polymorphic<'div', IntroductionContentProps>
