import { forwardRef } from 'react'

import { Polymorphic } from '../../../utils/PolymorphicUtils'
import { Prose } from '../../shared/prose/prose'
import { Stack } from '../../shared/stack/Stack'
import { ProjectData } from '../resume-page'
import { ProjectHistoryEntryBodyResponsibilities } from './project-history-entry-body-responsibilities'
import { ProjectHistoryEntryBodyTools } from './project-history-entry-body-tools'

export type ProjectHistoryEntryBodyProps = Pick<
  ProjectData,
  'descriptionHtml' | 'tools' | 'responsibilities'
> & {}

export const ProjectHistoryEntryBody = forwardRef(
  function ProjectHistoryEntryBody(
    { descriptionHtml, responsibilities, tools, ...props },
    ref,
  ) {
    return (
      <Stack direction="column" gap={4 * 5} {...props} ref={ref}>
        <Prose dangerouslySetInnerHTML={{ __html: descriptionHtml }} />
        <ProjectHistoryEntryBodyResponsibilities
          className="mt-3"
          responsibilities={responsibilities}
        />
        <ProjectHistoryEntryBodyTools tools={tools} />
      </Stack>
    )
  },
) as Polymorphic<'div', ProjectHistoryEntryBodyProps>
