import { forwardRef } from 'react'

import { Polymorphic } from '../../../utils/PolymorphicUtils'
import { Stack } from '../../shared/stack/Stack'
import { ResumeData } from '../resume-page'
import { IntroductionContent } from './introduction-content'
import { IntroductionImage } from './introduction-image'

export type IntroductionProps = Pick<ResumeData, 'introduction' | 'contacts'>

export const Introduction = forwardRef(function Introduction(
  { introduction, contacts, ...props },
  ref,
) {
  return (
    <Stack
      direction={{ sm: 'column-reverse', md: 'row' }}
      align={{ sm: 'center', md: 'start' }}
      justify="space-between"
      gap={{ sm: 12 * 4, md: 6 * 8 }}
      {...props}
      ref={ref}
    >
      <IntroductionContent
        introduction={introduction}
        contacts={contacts}
        className="md:max-w-4/6"
      />
      <IntroductionImage introduction={introduction} />
    </Stack>
  )
}) as Polymorphic<'div', IntroductionProps>
