import { forwardRef } from 'react'
import { useTranslation } from 'react-i18next'

import { Polymorphic } from '../../../utils/PolymorphicUtils'
import { Badge } from '../../shared/badge/badge'
import { Stack } from '../../shared/stack/Stack'
import { Typography } from '../../shared/typography/typography'
import { ProjectData } from '../resume-page'

export type ProjectHistoryEntryBodyToolsProps = Pick<ProjectData, 'tools'> & {}

export const ProjectHistoryEntryBodyTools = forwardRef(
  function ProjectHistoryEntryBodyTools({ tools, ...props }, ref) {
    const { t } = useTranslation()

    return (
      <Stack direction="column" gap={4 * 4} {...props} ref={ref}>
        <Typography scale="overline" emphasis="strong">
          {t('resume.projects.tools')}
        </Typography>
        <Stack
          wrap="wrap"
          gap={2 * 3}
          css={{ display: 'flex', ' @media print': { display: 'none' } }}
        >
          {tools.map((tool) => (
            <Badge key={tool} size="sm" variant="outline">
              {tool}
            </Badge>
          ))}
        </Stack>
        <Stack
          wrap="wrap"
          gap={2 * 3}
          css={{ display: 'none', ' @media print': { display: 'flex' } }}
        >
          {tools.filter(Boolean).map((tool, index) => (
            <Typography key={tool} scale="caption" emphasis="default">
              {tool}
              {index !== tools.length - 1 ? ' | ' : ''}
            </Typography>
          ))}
        </Stack>
      </Stack>
    )
  },
) as Polymorphic<'div', ProjectHistoryEntryBodyToolsProps>
