import { forwardRef } from 'react'

import { Polymorphic } from '../../utils/PolymorphicUtils'
import { Container } from '../shared/container/container'
import { Stack } from '../shared/stack/Stack'
import { Introduction } from './introduction/introduction'
import { ProjectHistory } from './project-history/project-history'

export type ResumeData = {
  introduction: IntroductionData
  contacts: ContactsData
  projects: Array<ProjectData>
}

export type IntroductionData = {
  jobTitle: string
  name: string
  description: string

  imageSrc: string
}

export type ContactsData = {
  phone: string
  email: string
}

export type ProjectData = {
  role: string
  industry: string
  categories: Array<string>
  title: string
  tools: Array<string>
  responsibilities: Array<string>
  descriptionHtml: string
}

export type ResumePageProps = {
  data: ResumeData
}

export const ResumePage = forwardRef(function ResumePage(
  { as: Component = 'main', data, className, ...props },
  ref,
) {
  return (
    <Component
      className={`relative z-10 flex-1 ${className ?? ''}`}
      {...props}
      ref={ref}
    >
      <Container className="py-8 pb-16 md:pb-24 print:py-0 print:pb-0">
        <Stack direction="column" gap={4 * 8}>
          <Introduction
            introduction={data.introduction}
            contacts={data.contacts}
          />
          <ProjectHistory projects={data.projects} />
        </Stack>
      </Container>
    </Component>
  )
}) as Polymorphic<'main', ResumePageProps>
