import { graphql, useStaticQuery } from 'gatsby'
import * as React from 'react'
import { Helmet } from 'react-helmet'
import { useTranslation } from 'react-i18next'
import { useQueryParamString } from 'react-use-query-param-string'

import { ProjectData, ResumePage } from '../components/resume/resume-page'
import { resume as resumeDe } from '../data/resume/de'
import { resume as resumeEn } from '../data/resume/en'
import { SupportedLanguages } from '../i18n/config'

type ProjectNode = {
  sourceInstanceName: SupportedLanguages
  project: {
    frontmatter: {
      title: string
      role: string
      sector: string
      from: string | null
      to: string | null
      categories?: Array<string>
      tasks: Array<string>
      tools: Array<string>
    }
    html: string
  } | null
}

type DataProps = {
  files: {
    projects: ProjectNode[]
  }
}

const Resume = () => {
  const { i18n } = useTranslation()
  const [categoryFilter] = useQueryParamString('category', '')
  const currentLanguage = i18n.resolvedLanguage as SupportedLanguages

  const normalizedForFilter = (input: string) =>
    input.replace(/[^a-zA-Z0-9]/g, '').toLowerCase()

  const matchesCategoryFilter = (project: ProjectData) => {
    if (!categoryFilter || categoryFilter.length === 0) {
      return true
    }

    return (project.categories ?? []).some((categoryInProject) =>
      categoryFilter
        .split(',')
        .some(
          (categoryInFilter) =>
            normalizedForFilter(categoryInFilter) ===
            normalizedForFilter(categoryInProject),
        ),
    )
  }

  const data = useStaticQuery<DataProps>(graphql`
    query LegacyPageProjectsQuery {
      files: allFile(
        filter: {
          sourceInstanceName: { in: ["en", "de"] }
          childMarkdownRemark: { frontmatter: { hidden: { ne: true } } }
        }
        sort: { childMarkdownRemark: { frontmatter: { from: DESC } } }
      ) {
        projects: nodes {
          sourceInstanceName
          project: childMarkdownRemark {
            frontmatter {
              role
              sector
              tasks
              title
              categories
              tools
              from(formatString: "YYYY-MM-01")
              to(formatString: "YYYY-MM-01")
            }
            html
          }
        }
      }
    }
  `)

  const dataByLanguage = {
    en: resumeEn,
    de: resumeDe,
  }

  const resumePageData = dataByLanguage[currentLanguage]

  const projects: Array<ProjectData> = data.files.projects
    .filter(
      (
        projectNode,
      ): projectNode is ProjectNode & {
        project: NonNullable<ProjectNode['project']>
      } =>
        projectNode.sourceInstanceName === currentLanguage &&
        projectNode.project !== null,
    )
    .map(
      (projectNode) =>
        ({
          role: projectNode.project.frontmatter.role,
          industry: projectNode.project.frontmatter.sector,
          title: projectNode.project.frontmatter.title,
          descriptionHtml: projectNode.project.html,
          tools: projectNode.project.frontmatter.tools,
          responsibilities: projectNode.project.frontmatter.tasks,
          categories: projectNode.project.frontmatter.categories,
        }) as ProjectData,
    )
    .filter(matchesCategoryFilter)

  return (
    <React.Fragment>
      <Helmet
        title={resumePageData.introduction.name}
        htmlAttributes={{ lang: currentLanguage === 'de' ? 'de-DE' : 'en-GB' }}
      />
      <ResumePage data={{ projects, ...resumePageData }} />
    </React.Fragment>
  )
}

export default Resume
